  xm18 P001 N012 0 0 sky130_fd_pr__nfet_01v8 w={W_xm18} l={L_xm18}
.ends SUB_1

.control
* 1. DC Operating Point & Power
op
let pwr = -i(vdd) * 1.8
print pwr
print v(out) v(in) v(vbias1) v(vbias2) v(vbias3) v(vbias4)

* 2. AC Transimpedance Analysis
ac dec 20 1k 100Meg
let zt_db = vdb(out)
let phase_zt = 180/PI * cph(v(out))
let zin_db = vdb(in)

meas ac zt_100k find zt_db at=100k
meas ac phase_100k find phase_zt at=100k
meas ac zin_100k find zin_db at=100k

* 3. Transient Integration Analysis (Baker CMOSedu command: .tran 30u)
tran 10n 30u
meas tran v_out_start find v(out) at=1u
meas tran v_out_end find v(out) at=29u
let ramp_rate = (v(out)[2900] - v(out)[100]) / 28e-6
print ramp_rate

quit
.endc
.end

